L29_1.m_Talk_TWN = "本來天空島村莊的居民對侵蝕現象的防備就沒有做好。"
L29_1.m_Talk_SCN = "本来天空岛村庄的居民对侵蚀现象的防备就没有做好。"
L29_1.m_Talk_DEU = "The floating island villages never had proper defenses against the Counterside Effect."
L29_1.m_Talk_FRA = "The floating island villages never had proper defenses against the Counterside Effect."
