L34_1.m_Talk_KOREA = "관리를 명목으로 섣부르게 간섭하려다간, 훗날 그들의 문명 자체가 사라지고 말 거야."
L34_1.m_fTalkTime = 0.03
L34_1.m_Talk_JPN = "管理という建前で無闇に干渉しては、いずれ彼らの文明は滅んでしまう。"
L34_1.m_Talk_ENG = "If we intrude rashly under the pretense of management, their civilization itself could vanish one day."
