L36_1 = "この矢じりは世界を超えて、<color=#ffd34c>特定の場所</color>に反応することに気づいたのじゃ。"
L35_1.m_Talk_JPN = L36_1
L36_1 = "I found this arrowhead reacts only beyond worlds at a <color=#ffd34c>specific location</color>."
